content.text:
{
  "name": "ROSBridge WebSocket连接组件",
  "name_en": "ROSBridge WebSocket Connection Component",
  "manufacturer": "",
  "description": "用于与ROSBridge服务器建立并维护WebSocket通信的非物理软件组件，可在实验系统中发送字符串消息、接收消息，并将收到的数据分发给已注册的回调函数。",
  "description_en": "A non-physical software component that establishes and maintains WebSocket communication with a ROSBridge server, used in lab systems to send string messages, receive incoming messages, and dispatch received data to registered callbacks.",
  "actions": [
    {
      "action_name": "auto-on_open",
      "description": "处理WebSocket连接打开事件。",
      "description_en": "Handle the WebSocket connection-open event."
    },
    {
      "action_name": "auto-sendString",
      "description": "通过WebSocket发送字符串消息。",
      "description_en": "Send a string message through the WebSocket connection."
    },
    {
      "action_name": "auto-on_error",
      "description": "处理WebSocket连接错误事件。",
      "description_en": "Handle a WebSocket connection error event."
    },
    {
      "action_name": "auto-on_close",
      "description": "处理WebSocket连接关闭事件。",
      "description_en": "Handle the WebSocket connection-close event."
    },
    {
      "action_name": "auto-run",
      "description": "启动并运行WebSocket连接过程。",
      "description_en": "Start and run the WebSocket connection process."
    },
    {
      "action_name": "auto-on_message",
      "description": "处理收到的消息并调用已注册的回调函数。",
      "description_en": "Handle an incoming message and invoke registered callbacks."
    },
    {
      "action_name": "auto-registerCallback",
      "description": "注册用于处理收到消息的回调函数。",
      "description_en": "Register a callback function for handling incoming messages."
    }
  ],
  "tag_hints": [
    "ROSBridge",
    "WebSocket communication",
    "ROS message transport",
    "callback dispatch",
    "robot software integration",
    "network messaging"
  ]
}

